import * as THREE from 'three';
import Stats from 'stats.js';
import { ThreeCore } from '..';

export class RendererWrapper {
	public core: ThreeCore;
	public scene: THREE.Scene;
	public renderer: THREE.WebGLRenderer;

	private _stats: Stats;
	private _clock: THREE.Clock;
	private _initPost = true;
	private _antialias = true;

	private _adaptiveRendering = false;
	private _keepRendering = true;
	private _forceRenderActive = false;
	private _isRendering = false;

	private idleTime = 0;
	private readonly MAX_IDLE_SECONDS = 0.1;

	public requestFrame: number;
	public deltaTime = 0;
	public t = 0;

	public divRenderingStatus: HTMLDivElement;

	constructor(threeCore: ThreeCore, enableAdaptiveRendering = true) {
		this.core = threeCore;
		THREE.Object3D.DEFAULT_UP.copy(this.core.upVector);
		this.init();
		this.initBinding();
		this.keepRendering = true;
		this.adaptiveRendering = enableAdaptiveRendering;
	}

	private init() {
		this.scene = new THREE.Scene();
		this.scene.background = new THREE.Color(0xffffff);
		this.scene.castShadow = true;

		this.renderer = new THREE.WebGLRenderer({
			antialias: this._antialias,
			alpha: !this.core.isPerformanceMode,
			powerPreference: 'high-performance',
		});
		this.renderer.setPixelRatio(this.core.host.clientWidth / this.core.host.clientHeight);
		this.renderer.setSize(this.core.host.clientWidth, this.core.host.clientHeight);
		window.addEventListener('resize', this.resizeHandler);

		this.renderer.shadowMap.enabled = true;
		this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
		this.renderer.toneMapping = THREE.ACESFilmicToneMapping;

		this.renderer.toneMappingExposure = 1.0;
		this.renderer.outputColorSpace = THREE.SRGBColorSpace;
		this.renderer.localClippingEnabled = true;

		this.renderer.domElement.id = 'hypercube-renderer';
		this.core.host.appendChild(this.renderer.domElement);
	}

	private initBinding() {
		this.core.scene = this.scene;
		this.core.renderer = this.renderer;
	}

	public toggleAdaptiveRendering() {
		this.adaptiveRendering = !this.adaptiveRendering;
	}

	public get adaptiveRendering() {
		return this._adaptiveRendering;
	}

	public set adaptiveRendering(value: boolean) {
		if (this._adaptiveRendering === value) return;
		this._adaptiveRendering = value;
		this.keepRendering = !value;
		this.idleTime = 0;
		this.loop();
	}

	public get keepRendering() {
		return this._keepRendering;
	}

	public set keepRendering(value: boolean) {
		if (this._keepRendering === value) return;
		this._keepRendering = value;
		this._clock?.start();
		this.loop();
	}

	public renderForce() {
		if (this._isRendering) {
			this.idleTime = 0;
			return;
		}

		if (this._adaptiveRendering) {
			this._forceRenderActive = true;
			this.keepRendering = true;
		} else {
			this.keepRendering = true;
		}
	}

	public start() {
		this.removeLoadingGIFDom();

		this._stats = new Stats();
		this._stats.showPanel(0);
		Object.assign(this._stats.dom.style, {
			position: 'absolute',
			top: '0px',
			right: '0px',
			left: '',
		});
		this.core.host.appendChild(this._stats.dom);

		this.divRenderingStatus = document.createElement('div');
		Object.assign(this.divRenderingStatus.style, {
			fontSize: '11px',
			color: '#181835',
			fontWeight: '300',
		});
		this._stats.dom.appendChild(this.divRenderingStatus);

		this._clock = new THREE.Clock();
		this._initPost = false;

		this.core.initUI();
	}

	public loop = () => {
		if (this._adaptiveRendering && !this._keepRendering && this.idleTime >= this.MAX_IDLE_SECONDS) {
			this.divRenderingStatus.textContent = 'Stop rendering.';
			this._isRendering = false;
			return;
		}

		this.requestFrame = requestAnimationFrame(this.loop);
		if (this.divRenderingStatus) this.divRenderingStatus.textContent = 'rendering...';

		this.deltaTime = this._clock?.getDelta();
		this.t += this.deltaTime;

		if (!this.core.readyBinding() || !this.core.ready) return;

		if (this._initPost) this.start();

		this._stats.begin();
		this._isRendering = true;

		this.core.cameraWrapper.update();

		const sceneUpdated = this.core.update();

		if (sceneUpdated || !this._adaptiveRendering || this._keepRendering) {
			this.idleTime = 0;
		} else {
			this.idleTime += this.deltaTime;
		}

		this.core.postProcessingWrapper.render();
		this._stats.end();

		if (this._forceRenderActive) {
			this._forceRenderActive = false;
			this.keepRendering = false;
		}
	};

	private removeLoadingGIFDom() {
		document.getElementById('loading')?.remove();
	}
	private resizeHandler = () => {
		const width = this.core.host.clientWidth;
		const height = this.core.host.clientHeight;

		this.renderer.setPixelRatio(window.devicePixelRatio); // 보통 이게 더 정확함
		this.renderer.setSize(width, height);

		if (this.core.cameraWrapper.camera instanceof THREE.PerspectiveCamera) {
			this.core.cameraWrapper.camera.aspect = width / height;
			this.core.cameraWrapper.camera.updateProjectionMatrix();
		}

		this.renderForce();
	};
	public disposeScene() {
		cancelAnimationFrame(this.requestFrame);
		this.requestFrame = undefined;

		this.scene.traverse((object) => {
			if ((object as any).geometry?.dispose) {
				(object as any).geometry.dispose();
			}

			const material = (object as any).material;
			if (material) {
				const disposeTexture = (tex: any) => {
					if (tex && typeof tex.dispose === 'function') {
						tex.dispose();
					}
				};

				if (Array.isArray(material)) {
					material.forEach((m) => {
						disposeTexture(m.map);
						disposeTexture(m.normalMap);
						disposeTexture(m.roughnessMap);
						disposeTexture(m.metalnessMap);
						disposeTexture(m.bumpMap);
						disposeTexture(m.alphaMap);
						disposeTexture(m.emissiveMap);
						m.dispose?.();
					});
				} else {
					disposeTexture(material.map);
					disposeTexture(material.normalMap);
					disposeTexture(material.roughnessMap);
					disposeTexture(material.metalnessMap);
					disposeTexture(material.bumpMap);
					disposeTexture(material.alphaMap);
					disposeTexture(material.emissiveMap);
					material.dispose?.();
				}
			}
		});

		const disposeEnvTexture = (tex: any) => {
			if (tex && typeof tex.dispose === 'function') {
				tex.dispose();
			}
		};
		disposeEnvTexture(this.scene.background);
		disposeEnvTexture(this.scene.environment);

		this.scene.background = null;
		this.scene.environment = null;

		const lights: THREE.Object3D[] = [];
		this.scene.traverse((obj) => {
			if (obj instanceof THREE.Light) {
				lights.push(obj);
			}
		});
		lights.forEach((light) => {
			this.scene.remove(light);
		});

		this.scene.clear();
	}
}
